<?php require __DIR__.'/../app/bootstrap.php';$u=require_seller();require_commerce();$title=t('Incoming orders');$orders=all('SELECT * FROM orders WHERE seller_id=? ORDER BY id DESC',[$u['id']]);require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><h1><?=e(t('Incoming Orders'))?></h1><p><?=e(t('Prepare pickup and delivery orders for your customers.'))?></p></div><section class="panel"><?php if(!$orders): ?><p class="empty"><?=e(t('New customer orders will appear here.'))?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?=e(t('Order'))?></th><th><?=e(t('Customer'))?></th><th><?=e(t('Method'))?></th><th><?=e(t('Total'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Action'))?></th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><?=e($order['reference'])?></td><td><?=e($order['customer_name'])?></td><td><?=e(t(ucfirst($order['fulfillment'])))?></td><td><?=money((int)$order['total_paisa'])?></td><td><?=e(status_label($order))?></td><td><a class="pill compact" href="<?=e(url('seller/order.php?id='.$order['id']))?>"><?=e(t('Manage →'))?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
